IEnumerable<int> Zahlen()
{
  Console.WriteLine("Start");
  for (int i = 1; i <= 3; i++)
  {
    Console.WriteLine($"liefere {i}");
    yield return i;
  }
}
var z = Zahlen();
Console.WriteLine("vor foreach");
foreach (var x in z)
  Console.WriteLine($"bekomme {x}");

IEnumerable<double> LeseWerte(
    string pfad)
{
  foreach (var zeile in File
      .ReadLines(pfad).Skip(1))
  {
    var t = zeile.Split(';');
    if (double.TryParse(t[1],
          out double w))
      yield return w;
  }
}
// 1 000 000 Zeilen, Werte 20–29:
var werte = LeseWerte("mess.csv");
Console.WriteLine(werte.Average());
// 24.5
